"""Make a standalone viewer from actual original/native/WASM full cell captures."""
import base64,gzip,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];folder=ROOT/'evidence/original-atelier-application-particles-20261014';packed=(folder/'frames.json.gz').read_bytes();rows=json.loads(gzip.decompress(packed));words=136*44*4
assert len(rows)==201
for r in rows:
 assert len(r['original'])==words and len(r['expected'])==words
 assert r['native']==r['expected']==r['wasm']
manifest=dict(samples=len(rows),dimensions=[136,44],wordsPerFrame=words,allWordsCompared=True,masks=False,nativeExact=True,wasmExact=True,sourceHtmlSha256='01500ccd3106f40a7f0b3e21fe4a580f1e0666980e998930feaf94bff730aced',capturesSha256=hashlib.sha256(packed).hexdigest(),idMapping='Original semantic window/action/dock IDs mapped explicitly to current native ID domains; every resulting word compared.',cases=[r['case']['name'] for r in rows])
(folder/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
encoded=base64.b64encode(packed).decode()
html=r"""<!doctype html><html lang=en><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Nocturne original Atelier application particles</title><style>body{background:#101319;color:#dfd8cc;font:16px/1.5 system-ui;margin:30px}h1{font-size:28px}select{font:inherit;padding:8px;background:#222630;color:inherit;max-width:100%}.frames{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{margin:0}canvas{width:100%;background:#101319}figcaption{padding:8px 0;color:#abc3b9}a{color:#abc3b9}@media(max-width:900px){.frames{grid-template-columns:1fr}}</style><h1>Original Atelier application particles</h1><p>201 complete original frames match native C and import-free WASM exactly. Embers, sparks, nova, rain, snow and inherited ripple behavior include original defaults, 34 control endpoints, reduced motion, fractional and signed event IDs, clipped glows, trails, last16 order, automatic novas, expired and future events. The original background, stars, windows and input chrome are included.</p><p>Semantic hit IDs are translated into their current native domains before all four words per cell are compared. No cells or color channels are masked. <a href=manifest.json>Evidence manifest</a> · <a href=frames.json.gz>Raw captured frames</a></p><select id=case aria-label="Captured frame"></select><p id=status>Loading preserved cell buffers…</p><div class=frames><figure><figcaption>Retained original JavaScript renderer</figcaption><canvas id=original></canvas></figure><figure><figcaption>Current native C</figcaption><canvas id=native></canvas></figure><figure><figcaption>Current public WASM ABI</figcaption><canvas id=wasm></canvas></figure></div><script>
const packed='@@DATA@@';
function paint(id,words){const c=document.getElementById(id),w=136,h=44,cw=9,ch=16;c.width=w*cw;c.height=h*ch;const ctx=c.getContext('2d');ctx.font='14px monospace';ctx.textBaseline='top';const rgb=n=>'#'+n.toString(16).padStart(6,'0');for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*4,g=words[i],px=x*cw,py=y*ch;ctx.fillStyle=rgb(words[i+2]);ctx.fillRect(px,py,cw,ch);ctx.fillStyle=rgb(words[i+1]);if(g===0x2580)ctx.fillRect(px,py,cw,ch/2);else if(g===0x2584)ctx.fillRect(px,py+ch/2,cw,ch/2);else if(g===0x2588)ctx.fillRect(px,py,cw,ch);else if(g>=0x2800&&g<=0x28ff){const d=[[.2,.1],[.2,.3],[.2,.55],[.7,.1],[.7,.3],[.7,.55],[.2,.8],[.7,.8]];for(let k=0;k<8;k++)if((g-0x2800)&(1<<k))ctx.fillRect(px+d[k][0]*cw,py+d[k][1]*ch,cw*.2,ch*.1)}else if(g>32)ctx.fillText(String.fromCodePoint(g),px,py,cw)}}
(async()=>{const bytes=Uint8Array.from(atob(packed),x=>x.charCodeAt(0)),stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')),rows=JSON.parse(await new Response(stream).text()),selector=document.getElementById('case');rows.forEach((r,i)=>selector.add(new Option(r.case.name,i)));function show(){const r=rows[Number(selector.value)];for(const k of ['original','native','wasm'])paint(k,r[k]);let differences=0;for(let i=0;i<r.expected.length;i++)if(r.native[i]!==r.expected[i]||r.wasm[i]!==r.expected[i])differences++;document.getElementById('status').textContent=r.case.name+' — '+differences+' differing words / '+r.expected.length;document.documentElement.dataset.ready='true'}selector.onchange=show;show()})()
</script></html>""".replace('@@DATA@@',encoded)
(folder/'report.html').write_text(html);print('201 exact full frame captures verified; report written')
